type ObfuscatedTO struct {
	ID     string            `json:"id"`
	plain  map[string]string // unprotected pairs, marshalled explicitly
	sealed []byte            // AEAD(gob(protected)) written by Seal; String() masks logs
}

func (t *ObfuscatedTO) Seal(key []byte) error {
	aead, err := cipher.NewGCM(must(aes.NewCipher(key)))  // 32-byte key from the key store
	if err != nil { return err }
	nonce := make([]byte, aead.NonceSize())               // random and unique per seal
	t.sealed = aead.Seal(nonce, nonce, mustGob(t.protected), nil)
	t.protected = nil                                     // drop the plaintext copy
	return nil
}
